SET NOCOUNT ON;SET XACT_ABORT ON;DECLARE @UserDelta bigint=(SELECT w.UserPages-b.UserPages FROM lab.Evidence w CROSS JOIN lab.Evidence b WHERE w.Stage='WORKLOAD' AND b.Stage='BASELINE'),@InternalDelta bigint=(SELECT w.InternalPages-b.InternalPages FROM lab.Evidence w CROSS JOIN lab.Evidence b WHERE w.Stage='WORKLOAD' AND b.Stage='BASELINE');SELECT @UserDelta UserPageDelta,@InternalDelta InternalPageDelta,N'Version Store ist ein eigener Snapshot-Scope' ScopeNote;IF @InternalDelta<=0 BEGIN PRINT 'SQLPERF_SUMMARY|WARN|WARN_EMPIRICAL_VARIANCE';RETURN;END;PRINT 'SQLPERF_SUMMARY|PASS|OK';
